/bin/bash -lc "PYTHONPATH=lib python - <<'PY'
from ansible.template import Templar
for filter_name in ('to_yaml', 'to_nice_yaml'):
    try:
        print(Templar(variables={}).template('{{ MYSVC_ENV | %s }}' % filter_name))
    except Exception as e:
        print(filter_name, type(e).__name__, str(e), 'orig=', type(getattr(e,'orig_exc',None)).__name__)
PY"

